using System;
using System.Collections.Generic;
using System.Text.RegularExpressions;
namespace ShopTogether {
    // Message tokens are resolved only at the UI boundary, in the recipient's language.
    internal static class Loc {
        static readonly Regex Tokens = new Regex(@"~SMC(\d{3})~", RegexOptions.CultureInvariant);
        static readonly Dictionary<string,string> Cache = new Dictionary<string,string>();
        static int cachedLanguage=-1;
        internal static int Language {
            get {
                string code="";
                try { code=LocHelper.GetCurrentLocaleCode(); } catch { }
                if(string.IsNullOrEmpty(code)) { try { code=Steamworks.SteamApps.GetCurrentGameLanguage(); } catch { } }
                code=(code??"").ToLowerInvariant().Replace('_','-');
                if(code=="tchinese"||code.Contains("hant")||code=="zh-tw"||code=="zh-hk")return 0;
                if(code=="schinese"||code.StartsWith("zh"))return 1;
                if(code.StartsWith("ja"))return 3;
                if(code.StartsWith("es")||code=="spanish"||code=="latam")return 4;
                if(code.StartsWith("ko"))return 5;
                if(code.StartsWith("fr"))return 6;
                if(code.StartsWith("ru"))return 7;
                return 2;
            }
        }
        internal static string Text(string value) {
            if(string.IsNullOrEmpty(value)||value.IndexOf("~SMC",StringComparison.Ordinal)<0)return value;
            int lang=Language; if(cachedLanguage!=lang){Cache.Clear();cachedLanguage=lang;}
            string rendered;if(Cache.TryGetValue(value,out rendered))return rendered;
            rendered=Tokens.Replace(value,m=>{int id;return int.TryParse(m.Groups[1].Value,out id)&&id>0&&id<=Rows.Length?Rows[id-1][lang]:m.Value;});
            if(Cache.Count>=512)Cache.Clear();Cache[value]=rendered;return rendered;
        }
